parameters.jsCode:
const originalData = $('When Executed by Another Workflow').first().json;

const rawOutput = $input.first().json.output || '';

let aiData = {
  primary_type: 'Error: I couldn`t figure out the content type.',
  secondary_type: null
};

const jsonMatch = rawOutput.match(/{[\s\S]*}/);

if (jsonMatch && jsonMatch[0]) {
  try {
    aiData = JSON.parse(jsonMatch[0]);
  } catch (error) {
    console.log("Failed to parse JSON:", error);
  }
}

const finalResult = {
  ...originalData,
  ...aiData
};

return finalResult;

// --- 1. Подготовка данных ---

// Текст кластера для анализа
const clusterContent = $('Normalization1').first().json.content.toLowerCase();

// Все правила-кандидаты из Supabase
const potentialRules = $input.all().map(item => item.json);


// --- 2. Фильтрация по ключевым словам ---
// Отбираем все правила, которые подходят по содержанию
const matchedRules = potentialRules.filter(rule => {
  // Правило без ключевых слов (общее) всегда проходит
  if (!rule.keywords || rule.keywords.length === 0) {
    return true;
  }
  // Правило с ключевыми словами проходит, если есть хотя бы одно совпадение
  return rule.keywords.some(keyword => clusterContent.includes(keyword.toLowerCase()));
});


// --- 3. Выбор лучшего правила (Сортировка) ---
if (matchedRules.length > 0) {
  // Сортируем совпавшие правила. Логика:
  // 1. Правила с ключевыми словами важнее, чем без них.
  // 2. При равной специфичности, правила с большим priority важнее.
  matchedRules.sort((a, b) => {
    const aHasKeywords = a.keywords && a.keywords.length > 0;
    const bHasKeywords = b.keywords && b.keywords.length > 0;
    if (aHasKeywords !== bHasKeywords) {
      return bHasKeywords - aHasKeywords; // true (1) будет выше, чем false (0)
    }
    return b.priority - a.priority;
  });

  // Победитель - первое правило в отсортированном списке
  const winningRule = matchedRules[0];

  // --- 4. Возвращаем результат С ID КАНАЛОВ ---
  return [{
    json: {
      ...$('Normalization1').first().json,
      tov_rule: winningRule,
    }
  }];

} else {
  // Если после всех фильтров не осталось ни одного правила
  return [{
    json: {
      ...$('Normalization1').first().json,
      tov_rule: null,
    }
  }];
}

// 1. Получаем общие данные, которые нужно добавить к каждому элементу
const commonData = $('find relevant').first().json;

// 2. Получаем массив дефолтных тонов
const defaultTovs = $('Get default ToV').all();

// 3. Используем .map() для создания нового массива, где каждый элемент - это комбинация
const result = defaultTovs.map(tovItem => {
  // Для каждого tovItem создаем новый объект json
  return {
    json: {
      ...commonData,      // Сначала добавляем общие данные
      ...tovItem.json     // Затем добавляем данные конкретного default_tov
    }
  };
});

// 4. Возвращаем массив новых элементов
return result;

